import logging
import socket
from typing import Union

from .tcp import TcpPdu
from ..device_status import DeviceStatus
from ..exceptions import BadDeviceStatus, BadPortNumber, PduConnectionError, BadResponse


class TopYoung(TcpPdu):
    def __init__(
        self, host: str, port: int = 3000, timeout: Union[float, int] = 10, retry_timeout: Union[float, int] = 2
    ) -> None:
        super().__init__(host, port, timeout, retry_timeout)
        self.POWER_OFF_STATUS = "OFF"
        self.POWER_ON_STATUS = "ON"
        self._vendor_info, self._model, self._serial, self._revision = self._get_idn()
        self._revision = self._revision.strip().strip("Rev.")

        logging.info(
            f"IDN information is vendor({self._vendor_info}), model({self._model}), "
            f"revision({self._revision}), serial number({self._serial})"
        )
        self._verify_model()

    @property
    def _port_setting(self):
        """Dictionary of settings used to get PDU status/value"""
        return {
            DeviceStatus.OFF: self.POWER_OFF_STATUS,
            DeviceStatus.ON: self.POWER_ON_STATUS,
        }

    @property
    def model(self):
        return self._model

    def _verify_port(self, port):
        pass

    def _verify_model(self):
        if self.model != self._model:
            logging.warning(f"model information from device '{self.model}' does not match the expected '{self._model}'")

    def _build_command(self, port, status):
        """Build command for TCP-based PDU get/set status"""
        self._verify_port(port)
        if status is None:
            return f"READ:{port}\r\n"

        lower_status = str(status).lower()
        if lower_status in (DeviceStatus.ON, DeviceStatus.OFF):
            return f"SET:{port}:{self._port_setting[lower_status]}\r\n"

        raise BadDeviceStatus(status)

    def _set_port_status(self, port, status):
        response = super(TopYoung, self)._set_port_status(port, status)
        return self._parse_response(response)

    def _parse_response(self, response):
        """Parser for response from PDU"""
        logging.info(f"Response: {response}")
        return response.split(":")[-1].strip()

    def _get_idn(self):
        cmd = "*IDN?\r\n"
        try:
            response = self._execute_cmd_with_retry_on_timeout(cmd)
        except socket.error as e:
            logging.error(str(e))
            raise PduConnectionError()
        return [item.strip() for item in response.split(",")]

    def get_voltage(self, port: int) -> float:
        """
        response of the form READVOLTAGE:1:53.3
        """
        self._verify_port(port)
        command = f"READVOLTAGE:{port}\r\n"
        return self._get_measurement(port, "voltage", command)

    def get_current(self, port: int) -> float:
        """
        output of the form READCURRENT:1:4.2
        """
        self._verify_port(port)
        command = f"READCURRENT:{port}\r\n"
        return self._get_measurement(port, "current", command)

    def _get_measurement(self, port: int, name: str, command: str) -> float:
        logging.info(f"Fetching {name} value on port: {port}")
        try:
            response = self._execute_cmd_with_retry_on_timeout(command)
            value = float(response.split(":")[-1])
        except socket.error as e:
            logging.error(str(e))
            raise PduConnectionError(f"Error while fetching {name} value on port: {port}")
        except ValueError as e:
            raise BadResponse(str(e))
        return value


class TopYoungRTSC003186(TopYoung):
    MODEL = "RTS-C003-186"

    def __init__(self, host, **kwargs):
        super(TopYoungRTSC003186, self).__init__(host, **kwargs)

    @property
    def model(self):
        return self.MODEL

    def _verify_port(self, port):
        if port not in range(1, 7):
            raise BadPortNumber(f"port is {port}")
